class AsyncShotsGroup:
    """Asynchronous operations of the *Shots* group."""

    def __init__(self, transport: AsyncTransport) -> None:
        self._t = transport

    async def get_shots(
        self,
        *,
        sequence_id: Optional[str] = None,
        project_id: Optional[str] = None,
        parent_id: Optional[str] = None,
    ) -> list[Shot]:
        """Get shots.

        Get the shots. Add a query parameter for each column to filter on. If you are
        not an administrator, you must give project_id. With sequence_id, the route uses
        the project of the sequence. A vendor gets only the entities of their tasks,
        without the hidden metadata columns.

        Args:
            sequence_id: Get only the shots of this sequence
            project_id: Unique identifier of the project
            parent_id: Get only the entities of this parent

        ``GET /data/shots``
        """
        return await self._t.request(
            "GET",
            "/data/shots",
            params={"sequence_id": sequence_id, "project_id": project_id, "parent_id": parent_id},
            response_type=list[Shot],
        )

    async def get_all_shots(
        self,
        *,
        sequence_id: Optional[str] = None,
        project_id: Optional[str] = None,
        parent_id: Optional[str] = None,
    ) -> list[Shot]:
        """Get shots.

        Get the shots. Add a query parameter for each column to filter on. If you are
        not an administrator, you must give project_id. With sequence_id, the route uses
        the project of the sequence. A vendor gets only the entities of their tasks,
        without the hidden metadata columns.

        Args:
            sequence_id: Get only the shots of this sequence
            project_id: Unique identifier of the project
            parent_id: Get only the entities of this parent

        ``GET /data/shots/all``
        """
        return await self._t.request(
            "GET",
            "/data/shots/all",
            params={"sequence_id": sequence_id, "project_id": project_id, "parent_id": parent_id},
            response_type=list[Shot],
        )

    async def get_shots_with_their_tasks(
        self,
        *,
        project_id: Optional[str] = None,
        compact: Optional[bool] = None,
        stream: Optional[bool] = None,
        episode_id: Optional[str] = None,
        assigned_to: Optional[str] = None,
    ) -> list[GetShotsWithTheirTasksItem]:
        """Get shots with their tasks.

        Get the shots with the tasks of each shot. Filter with project_id or episode_id.
        Use episode_id=all to get all the episodes. A client gets the tasks without the
        studio fields. If you are not an administrator, you must give project_id. A
        vendor gets only the entities of their tasks, without the hidden metadata
        columns. The response can have an ETag. Send it in If-None-Match to get a 304
        response when the data did not change.

        Args:
            project_id: Get only the entities of this project
            compact: Encode shots and tasks as positional value arrays (halves the
                payload). Field names are given by the shot_fields and task_fields entries
                of the response, map values by name, never by hardcoded position.
            stream: Stream the response as NDJSON (one header line, then one shot per
                line) instead of a single JSON document, to keep server memory flat on large
                productions.
            episode_id: Get only the entities of this episode. Use all to get the
                entities of all the episodes.
            assigned_to: With any value, get only the shots that have a task assigned to
                you.

        ``GET /data/shots/with-tasks``
        """
        return await self._t.request(
            "GET",
            "/data/shots/with-tasks",
            params={
                "project_id": project_id,
                "compact": compact,
                "stream": stream,
                "episode_id": episode_id,
                "assigned_to": assigned_to,
            },
            response_type=list[GetShotsWithTheirTasksItem],
        )

