    async def get_quotas_of_project_for_task_type(
        self,
        project_id: str,
        task_type_id: str,
        *,
        count_mode: Optional[Literal["weighted", "weigtheddone", "feedback", "done"]] = None,
        studio_id: Optional[str] = None,
    ) -> dict[str, GetQuotasOfProjectForTaskTypeResponseValue]:
        """Get the quotas of a project for a task type.

        Get the quota statistics of each person of a project for a task type. A quota
        counts the shots that a person ended. The response also has a total. Clients
        cannot use this route.

        Args:
            project_id: Unique identifier of the project
            task_type_id: Unique identifier of the task type
            count_mode: How to count the shots: weighted, weighteddone, feedback or
                done. The default value is weighted. The weighted modes give each shot the
                part of its work time that is in the period. The other modes count each shot
                on its end date. The feedback modes end a shot at its first feedback. The
                done modes end a shot when it is done.
            studio_id: Get only the persons of this studio

        ``GET /data/projects/{project_id}/quotas/{task_type_id}``
        """
        return await self._t.request(
            "GET",
            "/data/projects/{project_id}/quotas/{task_type_id}",
            path_params={"project_id": project_id, "task_type_id": task_type_id},
            params={"count_mode": count_mode, "studio_id": studio_id},
            response_type=dict[str, GetQuotasOfProjectForTaskTypeResponseValue],
        )

    async def get_quotas_of_person_in_project(
        self,
        project_id: str,
        person_id: str,
        *,
        count_mode: Optional[Literal["weighted", "weigtheddone", "feedback", "done"]] = None,
        studio_id: Optional[str] = None,
    ) -> dict[str, GetQuotasOfPersonInProjectResponseValue]:
        """Get the quotas of a person in a project.

        Get the quota statistics of a person in a project. A quota counts the shots that
        the person ended. A manager or a supervisor of the project can read the quotas
        of all the persons. Other users can read their own quotas only. Clients cannot
        use this route.

        Args:
            project_id: Unique identifier of the project
            person_id: Unique identifier of the person
            count_mode: How to count the shots: weighted, weighteddone, feedback or
                done. The default value is weighted. The weighted modes give each shot the
                part of its work time that is in the period. The other modes count each shot
                on its end date. The feedback modes end a shot at its first feedback. The
                done modes end a shot when it is done.
            studio_id: Get only the persons of this studio

        ``GET /data/projects/{project_id}/quotas/persons/{person_id}``
        """
        return await self._t.request(
            "GET",
            "/data/projects/{project_id}/quotas/persons/{person_id}",
            path_params={"project_id": project_id, "person_id": person_id},
            params={"count_mode": count_mode, "studio_id": studio_id},
            response_type=dict[str, GetQuotasOfPersonInProjectResponseValue],
        )

    async def set_frames_of_shots_from_previews(
        self,
        project_id: str,
        task_type_id: str,
        *,
        episode_id: Optional[str] = None,
    ) -> SetFramesOfShotsFromPreviewsResponse:
        """Set the frames of the shots from the previews.

        Set the number of frames of each shot of a project from the last preview of the
        shot for a task type. Give episode_id to change only the shots of one episode.
        You must be a manager of the project.

        Args:
            project_id: Get only the entities of this project
            task_type_id: Unique identifier of the task type
            episode_id: Get only the entities of this episode

        ``POST /actions/projects/{project_id}/task-types/{task_type_id}/set-shot-nb-frames``
        """
        return await self._t.request(
            "POST",
            "/actions/projects/{project_id}/task-types/{task_type_id}/set-shot-nb-frames",
            path_params={"project_id": project_id, "task_type_id": task_type_id},
            params={"episode_id": episode_id},
            response_type=SetFramesOfShotsFromPreviewsResponse,
        )
